\version "2.27.2"
% automatically converted by musicxml2ly from 46h-Barline-Fermata.xml
\pointAndClickOff

%% additional definitions required by the score:
% This `\caesura` creates a light-light bar line where there isn't
% already a more significant bar line, and aligns its decorations
% (e.g., fermatas) to the bar line.
forBarLine =
{
  \once \set Staff.caesuraType = #'((underlying-bar-line . "||"))
  \once \set Staff.caesuraTypeTransform = ##f
  \caesura
}


\header {
  texidoc = "Fermatas over bar lines using <fermata> as a child of <barline>.
    The bar line between measure 1 and 2 has one red-colored fermata on the top,
    the bar line between measure 2 and 3 has two fermatas, one above and one
    below (the latter one with a ‘type=\"inverted\"’ attribute and in larger
    size)."
}
\layout {
  \context {
    \Staff
    printKeyCancellation = ##f
  }
  \context {
    \Score
    autoBeaming = ##f
  }
}
PartPOneVoiceOne = \relative f' {
  \clef "treble" \time 4/4 \key c \major f1 \forBarLine -\tweak color "#FF0000"
  \fermata | % 1
  f1 \forBarLine \fermata -\tweak font-size #5.207 _\fermata | % 2
  f1 \bar "|."
}


% The score definition
\score {
  <<
    \new Staff = "P1" <<
      \context Staff <<
        \override Staff.BarLine.allow-span-bar = ##f
        \mergeDifferentlyDottedOn
        \mergeDifferentlyHeadedOn
        \context Voice = "PartPOneVoiceOne" {
          \PartPOneVoiceOne
        }
      >>
    >>
  >>
  \layout {}
  % To create MIDI output, uncomment the following line:
  % \midi { \tempo 4 = 100 }
}
